import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.BzGQ_3Jc.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"TD SDK","text":"对接文档","tagline":"Android / iOS 聚合接入 · 文档 1.1.6 · SDK 1.1.2.8","actions":[{"theme":"brand","text":"从后台开始","link":"/01_后台配置"},{"theme":"alt","text":"Android 集成","link":"/02_Android集成"},{"theme":"alt","text":"iOS 集成","link":"/03_iOS集成"}]},"features":[{"title":"后台配置","details":"建应用、广告位、广告源和瀑布流。正式包只用您自己的 App ID / 广告位 ID。","link":"/01_后台配置"},{"title":"集成 SDK","details":"Android 走 Maven（Manifest、混淆）；iOS 走 CocoaPods（ATS、ATT、SKAdNetwork）。","link":"/02_Android集成"},{"title":"五种广告","details":"激励、插屏、开屏、横幅、原生。统一 Load → isReady → Show，不会自动展示。","link":"/05_激励视频"},{"title":"隐私默认开","details":"不必调用 setPrivacyUserAgree(true)。JinDai / AdGain 需要 OAID 或 IDFA。","link":"/04_初始化与隐私"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788436019000}'),i={name:"index.md"};function r(n,t,c,l,s,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<p>正式上线请使用后台为<strong>您的应用</strong>签发的 App ID、广告位 ID。正文示例一律写 <code>YOUR_APP_ID</code> / <code>YOUR_AD_UNIT_ID</code>。</p><p>SDK <strong>不会</strong>在 Load 成功后自动 Show。原生自渲染要先拼布局再 Show。完整字段与合规披露见 <a href="./隐私合规">隐私合规</a>。</p><h2 id="推荐顺序" tabindex="-1">推荐顺序 <a class="header-anchor" href="#推荐顺序" aria-label="Permalink to &quot;推荐顺序&quot;">​</a></h2><ol><li><a href="./01_后台配置">后台配置</a>：应用 → 广告位 → 广告源 → 瀑布流</li><li>只看您的端：<a href="./02_Android集成">Android 集成</a> 或 <a href="./03_iOS集成">iOS 集成</a></li><li><a href="./04_初始化与隐私">初始化</a>（用户同意隐私政策之后；仅主进程 / <code>didFinishLaunching</code>）</li><li>按格式抄 Load → <code>isReady</code> → Show</li><li><a href="./12_测试验收">测试验收</a></li></ol><h2 id="调用顺序-双端同一套" tabindex="-1">调用顺序（双端同一套） <a class="header-anchor" href="#调用顺序-双端同一套" aria-label="Permalink to &quot;调用顺序（双端同一套）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>Android</th><th>iOS</th></tr></thead><tbody><tr><td>1</td><td>用户同意隐私政策</td><td>同左；需要 IDFA 时先 ATT</td></tr><tr><td>2</td><td>主进程 <code>TDAdsSDK.initSdk</code></td><td><code>didFinishLaunching</code> 里 <code>initSdkWithAppId</code></td></tr><tr><td>3</td><td><code>new TDXxx(ctx, YOUR_AD_UNIT_ID)</code></td><td><code>initWithAdUnitId:</code></td></tr><tr><td>4</td><td><code>setAdListener</code></td><td><code>setAdListener:</code></td></tr><tr><td>5</td><td>可选尺寸 / <code>userId</code> 等</td><td>同左</td></tr><tr><td>6</td><td><code>loadAd</code></td><td><code>loadAd</code></td></tr><tr><td>7</td><td><code>isReady</code> 为 true 再 <code>showAd</code></td><td><code>isReady</code> 再 <code>showAdFrom:…</code></td></tr><tr><td>8</td><td>离开页面 <code>onDestroy</code></td><td><code>onDestroy</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>格式</th><th>类</th><th>容器</th></tr></thead><tbody><tr><td>激励</td><td><code>TDReward</code></td><td>无</td></tr><tr><td>插屏</td><td><code>TDInterstitial</code></td><td>无</td></tr><tr><td>开屏</td><td><code>TDSplash</code></td><td>近全屏 overlay</td></tr><tr><td>横幅</td><td><code>TDBanner</code></td><td>宽撑满、高 ≥50（JinDai 建议 ≥200）</td></tr><tr><td>原生</td><td><code>TDNative</code></td><td>≥250；自渲染先打 TAG 再 Show</td></tr></tbody></table>',7)])])}const D=d(i,[["render",r]]);export{A as __pageData,D as default};
